/// url = 'https://icr.healthcampaigns.org/StructureMap/DIGITBoundaryToICR'
/// name = 'DIGITBoundaryToICR'
/// title = 'DIGIT boundary to an ICRLocation admin unit'
/// status = 'draft'

// One DIGIT boundary (a row of the DigitBoundary Library) as an admin-unit
// ICRLocation. Mapping: project/digit.md, "Boundary → ICRLocation".
//
// The ids, systems and tag are those of the DIGIT demo tenant: ids are
// dgt-<code>, identifiers are under .../identifiers/digit-demo/.

uses "https://icr.healthcampaigns.org/StructureDefinition/DIGITBoundaryRow" alias DIGITBoundaryRow as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/StructureDefinition/Location" alias Location as target

group Boundary(source b : DIGITBoundaryRow, target bundle : Bundle) {
  b -> bundle.type = 'collection' "bundleType";
  b -> bundle.entry as e, e.resource = create('Location') as loc then Location(b, loc) "location";
}

group Location(source b : DIGITBoundaryRow, target loc : Location) {
  // dgt- and the code, each character not allowed in an id (such as `_`)
  // written as `-`. transform.py shortens an id longer than 64 characters
  // with a hash; a map cannot, so such a code stops the run.
  b.code as c check c.length() <= 60 -> loc.id = evaluate(c, 'dgt-' + $this.replaceMatches('[^A-Za-z0-9.-]', '-')) "id";
  b -> loc.meta as m then {
    b -> m.tag as t, t.system = 'https://icr.healthcampaigns.org/CodeSystem/icr-project-tag-cs', t.code = 'digit-demo', t.display = 'DIGIT demo' "tag";
    b -> m.profile = 'https://icr.healthcampaigns.org/StructureDefinition/ICRLocation' "profile";
  } "meta";
  // The boundary codes are identifiers under a system per hierarchy.
  b.code as c, b.hierarchyType as h -> loc.identifier as i, i.system = evaluate(h, 'https://icr.healthcampaigns.org/identifiers/digit-demo/boundary/' + $this.lower()), i.value = c "code";
  b.id as id where $this != '' -> loc.identifier as i, i.system = 'https://icr.healthcampaigns.org/identifiers/digit-demo/boundary-id', i.value = id "serverId";
  // DIGIT keeps boundary names in its localisation service, not with the
  // boundary, so the name is made from the code, as transform.py does: the
  // segments after the last numeric segment that has a non-numeric one after
  // it, as words, each run of letters starting with a capital (Python's
  // str.title(), so 7TH gives 7Th). NIGERIA_NI_02_18_09_KE_TUNGAN_NOMA gives
  // Ke Tungan Noma. A code of underscores only is its own name.
  b.code as c where $this.matches('[^_]').not() -> loc.name = c "nameIsCode";
  b.code as c where $this.matches('[^_]') -> loc.name = evaluate(c,
      $this.replaceMatches('^(.*_)?[0-9]+_+(.*[^0-9_].*)$', '$2')
        .split('_').where($this != '').join(' ')
        .lower().toChars()
        .aggregate(iif($total.length() = 0 or $total.substring($total.length() - 1).matches('[^A-Za-z]'),
                       $total + $this.upper(), $total + $this), '')) "name";
  b -> loc.status = 'active' "status";
  b -> loc.physicalType as pt, pt.coding as cd, cd.system = 'http://terminology.hl7.org/CodeSystem/location-physical-type', cd.code = 'jdn', cd.display = 'Jurisdiction' "physicalType";
  b -> loc.type as t, t.coding as cd, cd.system = 'https://icr.healthcampaigns.org/CodeSystem/icr-location-type-cs', cd.code = 'admin-unit', cd.display = 'Administrative unit' "adminUnit";
  // The DIGIT level as text: the boundary type, the hierarchy and the depth.
  b.boundaryType as bt, b.hierarchyType as h, b.level as n -> loc.type as t, t.text = append(bt, ' (DIGIT ', h, ' hierarchy, level ', n, ')') "level";
  // The boundary directly above, for all but the top boundaries.
  b.parent as p -> loc.partOf as r, r.reference = evaluate(p, 'Location/dgt-' + $this.replaceMatches('[^A-Za-z0-9.-]', '-')) "partOf";
}
